from pathlib import Path

# 1) Registry: preserve historical global registrations; add scoped slots only when needed.
p = Path('src/valuation_engine/evaluator_registry.py')
t = p.read_text(encoding='utf-8')
old = '''class EvaluatorRegistry:\n    def __init__(self) -> None:\n        self._evaluators: dict[ModelKey, DeterministicEvaluator] = {}\n\n    def register(self, evaluator: DeterministicEvaluator) -> None:\n        if evaluator.key in self._evaluators:\n            raise ValueError(f"duplicate evaluator registration: {evaluator.key}")\n        if not evaluator.required_assumption_keys:\n            raise ValueError("evaluator must declare required assumptions")\n        self._evaluators[evaluator.key] = evaluator\n\n    def get(self, key: ModelKey) -> DeterministicEvaluator:\n        try:\n            return self._evaluators[key]\n        except KeyError as exc:\n            raise KeyError(f"no exact evaluator registered for {key}") from exc\n\n    def evaluate(self, key: ModelKey, scenario: BoundScenario, *, segment_id: str) -> SegmentValuation:\n        evaluator = self.get(key)\n        missing = tuple(key for key in evaluator.required_assumption_keys if not _has_assumption(scenario, key))\n        if missing:\n            raise ValueError(\n                f"evaluator {evaluator.evaluator_id} missing assumptions for {scenario.scenario_id}: {', '.join(missing)}"\n            )\n        return evaluator.evaluate(scenario, segment_id=segment_id)\n\n    def keys(self) -> tuple[ModelKey, ...]:\n        return tuple(sorted(self._evaluators, key=lambda item: (item.archetype, item.method, item.version)))\n'''
new = '''class EvaluatorRegistry:\n    def __init__(self) -> None:\n        self._evaluators: dict[ModelKey, DeterministicEvaluator] = {}\n        self._segment_evaluators: dict[tuple[str, ModelKey], DeterministicEvaluator] = {}\n\n    def register(\n        self,\n        evaluator: DeterministicEvaluator,\n        *,\n        segment_id: str | None = None,\n    ) -> None:\n        if not evaluator.required_assumption_keys:\n            raise ValueError("evaluator must declare required assumptions")\n        if segment_id is None:\n            if evaluator.key in self._evaluators:\n                raise ValueError(f"duplicate evaluator registration: {evaluator.key}")\n            self._evaluators[evaluator.key] = evaluator\n            return\n        if not segment_id:\n            raise ValueError("segment-scoped evaluator registration requires segment_id")\n        scoped_key = (segment_id, evaluator.key)\n        if scoped_key in self._segment_evaluators:\n            raise ValueError(\n                f"duplicate evaluator registration for segment {segment_id}: {evaluator.key}"\n            )\n        self._segment_evaluators[scoped_key] = evaluator\n\n    def get(\n        self,\n        key: ModelKey,\n        *,\n        segment_id: str | None = None,\n    ) -> DeterministicEvaluator:\n        if segment_id is not None:\n            scoped = self._segment_evaluators.get((segment_id, key))\n            if scoped is not None:\n                return scoped\n        try:\n            return self._evaluators[key]\n        except KeyError as exc:\n            scope = f" for segment {segment_id}" if segment_id is not None else ""\n            raise KeyError(f"no exact evaluator registered for {key}{scope}") from exc\n\n    def evaluate(self, key: ModelKey, scenario: BoundScenario, *, segment_id: str) -> SegmentValuation:\n        evaluator = self.get(key, segment_id=segment_id)\n        missing = tuple(key for key in evaluator.required_assumption_keys if not _has_assumption(scenario, key))\n        if missing:\n            raise ValueError(\n                f"evaluator {evaluator.evaluator_id} missing assumptions for {scenario.scenario_id}: {', '.join(missing)}"\n            )\n        return evaluator.evaluate(scenario, segment_id=segment_id)\n\n    def keys(self) -> tuple[ModelKey, ...]:\n        keys = set(self._evaluators)\n        keys.update(key for _, key in self._segment_evaluators)\n        return tuple(sorted(keys, key=lambda item: (item.archetype, item.method, item.version)))\n\n    def has_scoped_registrations(self) -> bool:\n        return bool(self._segment_evaluators)\n\n    def registration_items(\n        self,\n    ) -> tuple[tuple[str | None, ModelKey, DeterministicEvaluator], ...]:\n        rows = [\n            (None, key, evaluator)\n            for key, evaluator in self._evaluators.items()\n        ]\n        rows.extend(\n            (segment_id, key, evaluator)\n            for (segment_id, key), evaluator in self._segment_evaluators.items()\n        )\n        return tuple(\n            sorted(\n                rows,\n                key=lambda item: (\n                    item[0] or "",\n                    item[1].archetype,\n                    item[1].method,\n                    item[1].version,\n                ),\n            )\n        )\n'''
if old not in t:
    raise SystemExit('EvaluatorRegistry block not found')
p.write_text(t.replace(old, new, 1), encoding='utf-8')

# 2) Composer: only duplicate exact ModelKeys become segment-scoped.
p = Path('src/valuation_engine/generic_valuation_plan.py')
t = p.read_text(encoding='utf-8')
if 'from collections import Counter\n' not in t:
    t = t.replace('from __future__ import annotations\n\n', 'from __future__ import annotations\n\nfrom collections import Counter\n', 1)
old = '''        seen: set[tuple[str, str, str]] = set()\n        for choice, family, version in resolved:\n            key = (choice.archetype, choice.method, version)\n            if key in seen:\n                continue\n            seen.add(key)\n            prefix = segment_assumption_prefix(method_choices, choice.segment_id)\n'''
new = '''        identity_counts = Counter(\n            (choice.archetype, choice.method, version)\n            for choice, _, version in resolved\n        )\n        seen_global: set[tuple[str, str, str]] = set()\n        for choice, family, version in resolved:\n            key = (choice.archetype, choice.method, version)\n            segment_scoped = identity_counts[key] > 1\n            if not segment_scoped:\n                if key in seen_global:\n                    continue\n                seen_global.add(key)\n            registration_segment = choice.segment_id if segment_scoped else None\n            prefix = segment_assumption_prefix(method_choices, choice.segment_id)\n'''
if old not in t:
    raise SystemExit('composer seen block not found')
t = t.replace(old, new, 1)
# Add segment_id keyword to the three core-family registry.register calls only.
t = t.replace('''                evaluator_registry.register(\n                    NormalizedMultipleEvaluator(\n                        choice.archetype,\n                        version=version,\n                        ebitda_key=f"{prefix}normalized_ebitda",\n                        multiple_key=f"{prefix}normalized_multiple",\n                    )\n                )\n''', '''                evaluator_registry.register(\n                    NormalizedMultipleEvaluator(\n                        choice.archetype,\n                        version=version,\n                        ebitda_key=f"{prefix}normalized_ebitda",\n                        multiple_key=f"{prefix}normalized_multiple",\n                    ),\n                    segment_id=registration_segment,\n                )\n''', 1)
t = t.replace('''                evaluator_registry.register(\n                    ExplicitFCFFDCFEvaluator(\n                        archetype=choice.archetype,\n                        method=choice.method,\n                        version=version,\n                        forecast_years=forecast_years,\n                        discount_rate=rate,\n                        discount_rate_path_id=rate_path,\n                        beta_path_id=beta_path,\n                        assumption_prefix=prefix,\n                    )\n                )\n''', '''                evaluator_registry.register(\n                    ExplicitFCFFDCFEvaluator(\n                        archetype=choice.archetype,\n                        method=choice.method,\n                        version=version,\n                        forecast_years=forecast_years,\n                        discount_rate=rate,\n                        discount_rate_path_id=rate_path,\n                        beta_path_id=beta_path,\n                        assumption_prefix=prefix,\n                    ),\n                    segment_id=registration_segment,\n                )\n''', 1)
t = t.replace('''                evaluator_registry.register(\n                    BacklogBurnDCFEvaluator(\n                        archetype=choice.archetype,\n                        method=choice.method,\n                        version=version,\n                        forecast_years=forecast_years,\n                        discount_rate=rate,\n                        discount_rate_path_id=rate_path,\n                        beta_path_id=beta_path,\n                        assumption_prefix=prefix,\n                    )\n                )\n''', '''                evaluator_registry.register(\n                    BacklogBurnDCFEvaluator(\n                        archetype=choice.archetype,\n                        method=choice.method,\n                        version=version,\n                        forecast_years=forecast_years,\n                        discount_rate=rate,\n                        discount_rate_path_id=rate_path,\n                        beta_path_id=beta_path,\n                        assumption_prefix=prefix,\n                    ),\n                    segment_id=registration_segment,\n                )\n''', 1)
p.write_text(t, encoding='utf-8')

# 3) Compiler: resolve required assumptions against the segment-specific evaluator.
p = Path('src/valuation_engine/valuation_plan_compiler.py')
t = p.read_text(encoding='utf-8')
old = '''            _candidate_for(\n                capability,\n                scenario_set=scenario_set,\n                evaluator_registry=evaluator_registry,\n            )\n'''
new = '''            _candidate_for(\n                capability,\n                scenario_set=scenario_set,\n                evaluator_registry=evaluator_registry,\n                segment_id=segment.segment_id,\n            )\n'''
if old not in t:
    raise SystemExit('candidate call block not found')
t = t.replace(old, new, 1)
old = '''def _candidate_for(\n    capability: MethodCapability,\n    *,\n    scenario_set: BoundScenarioSet,\n    evaluator_registry: EvaluatorRegistry,\n) -> SegmentMethodCandidate:\n'''
new = '''def _candidate_for(\n    capability: MethodCapability,\n    *,\n    scenario_set: BoundScenarioSet,\n    evaluator_registry: EvaluatorRegistry,\n    segment_id: str,\n) -> SegmentMethodCandidate:\n'''
if old not in t:
    raise SystemExit('candidate signature not found')
t = t.replace(old, new, 1)
t = t.replace('''        evaluator = evaluator_registry.get(key)\n''', '''        evaluator = evaluator_registry.get(key, segment_id=segment_id)\n''', 1)

# Hash: preserve v1 byte identity for all historical registries; use v2 only if scopes exist.
old_hash = '''    rows: list[dict[str, object]] = []\n    for key in registry.keys():\n        evaluator = registry.get(key)\n        required = tuple(evaluator.required_assumption_keys)\n        if not required or not all(\n            isinstance(item, str) and item for item in required\n        ):\n            raise ValueError(\n                f"evaluator {key!r} has an invalid required-assumption contract"\n            )\n        if len(required) != len(set(required)):\n            raise ValueError(\n                f"evaluator {key!r} declares duplicate required assumptions"\n            )\n        rows.append(\n            {\n                "archetype": key.archetype,\n                "method": key.method,\n                "version": key.version,\n                "required_assumption_keys": required,\n            }\n        )\n    return _stable_contract_hash(\n        {\n            "contract": "valuation_evaluator_registry/v1",\n            "evaluators": rows,\n        }\n    )\n'''
new_hash = '''    if not registry.has_scoped_registrations():\n        rows: list[dict[str, object]] = []\n        for key in registry.keys():\n            evaluator = registry.get(key)\n            required = tuple(evaluator.required_assumption_keys)\n            if not required or not all(\n                isinstance(item, str) and item for item in required\n            ):\n                raise ValueError(\n                    f"evaluator {key!r} has an invalid required-assumption contract"\n                )\n            if len(required) != len(set(required)):\n                raise ValueError(\n                    f"evaluator {key!r} declares duplicate required assumptions"\n                )\n            rows.append(\n                {\n                    "archetype": key.archetype,\n                    "method": key.method,\n                    "version": key.version,\n                    "required_assumption_keys": required,\n                }\n            )\n        return _stable_contract_hash(\n            {\n                "contract": "valuation_evaluator_registry/v1",\n                "evaluators": rows,\n            }\n        )\n\n    scoped_rows: list[dict[str, object]] = []\n    for segment_id, key, evaluator in registry.registration_items():\n        required = tuple(evaluator.required_assumption_keys)\n        if not required or not all(\n            isinstance(item, str) and item for item in required\n        ):\n            raise ValueError(\n                f"evaluator {key!r} has an invalid required-assumption contract"\n            )\n        if len(required) != len(set(required)):\n            raise ValueError(\n                f"evaluator {key!r} declares duplicate required assumptions"\n            )\n        scoped_rows.append(\n            {\n                "segment_id": segment_id,\n                "archetype": key.archetype,\n                "method": key.method,\n                "version": key.version,\n                "required_assumption_keys": required,\n            }\n        )\n    return _stable_contract_hash(\n        {\n            "contract": "valuation_evaluator_registry/v2",\n            "evaluators": scoped_rows,\n        }\n    )\n'''
if old_hash not in t:
    raise SystemExit('registry hash block not found')
t = t.replace(old_hash, new_hash, 1)
p.write_text(t, encoding='utf-8')

# 4) Regression: duplicate exact method identity must get separate prefixes.
p = Path('tests/test_generic_valuation_plan.py')
t = p.read_text(encoding='utf-8')
if 'test_registry_scopes_duplicate_exact_model_key_by_segment' not in t:
    t += '''\n\ndef test_registry_scopes_duplicate_exact_model_key_by_segment():\n    loader = composed_generic_registry_loader(\n        method_choices=(\n            SegmentMethodChoice("trading", "process_spread", "normalized_multiple"),\n            SegmentMethodChoice("recycling", "process_spread", "normalized_multiple"),\n        ),\n        forecast_years=5,\n    )\n    registry = loader(_context({}))\n    key = ModelKey("process_spread", "normalized_multiple", "1")\n    assert registry.has_scoped_registrations()\n    assert registry.get(key, segment_id="trading").required_assumption_keys == (\n        "trading_normalized_ebitda",\n        "trading_normalized_multiple",\n    )\n    assert registry.get(key, segment_id="recycling").required_assumption_keys == (\n        "recycling_normalized_ebitda",\n        "recycling_normalized_multiple",\n    )\n    with pytest.raises(KeyError, match="no exact evaluator"):\n        registry.get(key)\n\n\ndef test_unique_model_key_keeps_historical_global_registry_contract():\n    loader = composed_generic_registry_loader(\n        method_choices=(\n            SegmentMethodChoice("core", "process_spread", "normalized_multiple"),\n        ),\n        forecast_years=5,\n    )\n    registry = loader(_context({}))\n    key = ModelKey("process_spread", "normalized_multiple", "1")\n    assert not registry.has_scoped_registrations()\n    assert registry.get(key).required_assumption_keys == (\n        "normalized_ebitda",\n        "normalized_multiple",\n    )\n'''
    p.write_text(t, encoding='utf-8')
